#include <algorithm>
#include <functional>
#include <vector>

std::function<bool(int)> make_filter(int threshold) {
    return [threshold](int s) { return s >= threshold; };   // copy: safe to return.
    // return [&threshold](int s) { ... };  // dangling: threshold dies on return.
}

int main() {
    std::vector<int> scores{55, 72, 91, 64, 98};
    int threshold = 70;
    auto high = std::count_if(scores.begin(), scores.end(),
                              [threshold](int s) { return s >= threshold; });   // 3.

    int total = 0;
    std::for_each(scores.begin(), scores.end(),
                  [&total](int s) { total += s; });   // reference: updates total. 380.

    int calls = 0;
    auto counter = [calls]() mutable { return ++calls; };   // modifies its OWN copy.
    counter(); counter();                                   // outer calls is still 0.
    auto f = make_filter(80);                               // f(91) is true.
    (void)high; (void)f;
}
```

